// Word lists (25 Nov 2026). From SCOWL through the wordlist-english package (MIT), English and Australian
// spellings, sizes 10 to 60. Answers are common words in a fixed shuffled order (unkind or odd ones taken out),
// so everyone gets the same word on the same day. 6 letter answers are for Six Tries on Hard.
const V3 = '';
const V4 = '';
const V5 = '';
const V6 = '';
const cache: Record<number, Set<string>> = {};
const set = (n: number, s: string) => (cache[n] ??= (() => { const o = new Set<string>(); for (let i = 0; i < s.length; i += n) o.add(s.slice(i, i + n)); return o; })());
export const isWord = (w: string) => ({ 3: () => set(3, V3), 4: () => set(4, V4), 5: () => set(5, V5), 6: () => set(6, V6) } as Record<number, () => Set<string>>)[w.length]?.().has(w) || ANSWERS.includes(w) || ANSWERS6.includes(w);
